// Нормализация входящей заявки + детерминированный хеш для идемпотентности.
// Хеш считаем чистым JS (FNV-1a), чтобы не зависеть от NODE_FUNCTION_ALLOW_BUILTIN.
const body = ($json.body && typeof $json.body === 'object') ? $json.body : $json;

const s = (v) => (v === undefined || v === null) ? '' : String(v).trim();

const name    = s(body.name || body.fullname || body.contact_name);
const contact = s(body.contact || body.email || body.phone);
const message = s(body.message || body.text || body.comment || body.description);
const source  = s(body.source || body.utm_source || 'website');

// Канонизированная строка для хеша (нижний регистр, стабильный порядок ключей).
const canon = JSON.stringify({ name, contact, message, source }).toLowerCase();

function fnv1a(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0;
  }
  return ('00000000' + h.toString(16)).slice(-8);
}
// Складываем два прохода -> 16 hex-символов, меньше шанс коллизий.
const hash = fnv1a(canon) + fnv1a('salt::' + canon);

if (!name && !contact && !message) {
  // Пустая заявка — помечаем, но не роняем поток.
}

return [{
  json: { name, contact, message, source, hash, received_at: new Date().toISOString() }
}];

