// Парсинг ответа ИИ. Модель обязана вернуть строгий JSON, но мы не доверяем ей:
// вытаскиваем JSON-объект, валидируем, при мусоре -> fallback 'manual_review'.
const agent = $json;
let text = agent.output ?? agent.text ?? agent.response ?? '';
if (typeof text !== 'string') text = JSON.stringify(text);

function extractJson(t) {
  const a = t.indexOf('{');
  const b = t.lastIndexOf('}');
  if (a === -1 || b === -1 || b < a) return null;
  try { return JSON.parse(t.slice(a, b + 1)); } catch (e) { return null; }
}

// Нормализованные поля тянем из предыдущего шага (агент перезаписал item).
const norm = $('Код: Нормализация').item.json;
const allowed = ['lead', 'question', 'spam'];

let parsed = extractJson(text);
let fallback = false;

if (!parsed || typeof parsed !== 'object') { parsed = {}; fallback = true; }

let type = String(parsed.type || '').toLowerCase().trim();
if (!allowed.includes(type)) { type = 'manual_review'; fallback = true; }

const name    = String(parsed.name || norm.name || '').trim();
const contact = String(parsed.contact || norm.contact || '').trim();
const summary = String(parsed.summary || norm.message || '').trim().slice(0, 1000);

let budget = parsed.budget;
budget = (budget === undefined || budget === null) ? '' : String(budget).trim();

return [{
  json: {
    hash: norm.hash,
    type,
    name,
    contact,
    summary,
    budget,
    source: norm.source,
    raw_message: norm.message,
    is_spam: type === 'spam',
    fallback,
    received_at: norm.received_at,
    classifier_raw: text
  }
}];

// Спам: не уведомляем владельца, только фиксируем в логе выполнения n8n.
console.log('[LEAD-PIPELINE] SPAM отклонён:', {
  hash: $json.hash,
  contact: $json.contact,
  summary: $json.summary
});
return [{ json: { logged: true, reason: 'spam', hash: $json.hash } }];

